(function(root){'use strict';
const MODEL_KEY='build-intelligence-geo-v3',OPS_KEY='build-intelligence-demo-v2';
const clone=x=>JSON.parse(JSON.stringify(x));
function buildingId(model){if(model.buildingId)return model.buildingId;let h=2166136261;for(const c of model.elements.map(e=>e.id).sort().join('|'))h=Math.imul(h^c.charCodeAt(0),16777619);return 'building-'+(h>>>0).toString(16)}
function ids(model,e){const b=buildingId(model);return{buildingId:b,floorId:b+'-F'+e.floor,unitId:b+'-U'+e.unit,elementId:e.id}}
function reconcile(state,model){const b=buildingId(model),next=clone(state);next.archivedBuildings??={};if(next.buildingId&&next.buildingId!==b){next.archivedBuildings[next.buildingId]={requests:next.requests,records:next.records,notices:next.notices};const saved=next.archivedBuildings[b]||{requests:[],records:[],notices:[]};Object.assign(next,clone(saved));delete next.archivedBuildings[b]}next.buildingId=b;const byId=new Map(model.elements.map(e=>[e.id,e]));for(const row of [...next.requests,...next.records]){const e=byId.get(row.element);row.buildingId??=b;row.linkStatus=e&&row.buildingId===b?'linked':'unresolved';if(e)Object.assign(row,ids(model,e),{unit:e.unit})}next.materials=model.elements.map(e=>({id:e.id,element:e.id,name:e.name,material:e.material,installed:e.constructed,inspection:e.inspected,quality:'Q '+e.Q+' · M '+e.M+' · 출처: '+e.source,pipe:(model.connections||[]).filter(pair=>pair.includes(e.id)).map(pair=>pair.find(id=>id!==e.id)).join(', ')||'명시된 배관 연결 없음',note:e.spec||'규격 미연결',...ids(model,e)}));return next}
function validationDataset(raw,model){if(!raw||raw.buildingId!==buildingId(model)||!['field','expert','synthetic'].includes(raw.referenceType)||typeof raw.source!=='string'||!raw.source.trim()||typeof raw.reviewer!=='string'||!raw.reviewer.trim()||!/^\d{4}-\d{2}-\d{2}$/.test(raw.reviewedAt)||!Array.isArray(raw.cases)||!raw.cases.length||raw.cases.length>100)throw Error('같은 건물 ID, 출처·검토자·날짜와 1~100개 사례가 필요합니다.');const ids=new Set(model.elements.map(e=>e.id)),caseIds=new Set();for(const c of raw.cases){if(!c||typeof c.caseId!=='string'||caseIds.has(c.caseId)||!ids.has(c.anchorId)||!Array.isArray(c.evaluatedIds)||!c.evaluatedIds.length||new Set(c.evaluatedIds).size!==c.evaluatedIds.length||!Array.isArray(c.confirmedIds)||new Set(c.confirmedIds).size!==c.confirmedIds.length||c.evaluatedIds.some(id=>!ids.has(id)||id===c.anchorId)||c.confirmedIds.some(id=>!c.evaluatedIds.includes(id)))throw Error('사례 ID·기준 구조물·검토한 대상·확인된 결함 ID를 확인하세요.');caseIds.add(c.caseId)}return clone(raw)}
function compare(dataset,model,G,options={},radius=4){const totals={spatial:{tp:0,fp:0,fn:0,ignored:0},distance:{tp:0,fp:0,fn:0,ignored:0}};const cases=dataset.cases.map(c=>{const e=model.elements.find(e=>e.id===c.anchorId),scope=new Set(c.evaluatedIds);const predicted={spatial:G.candidates(model,c.anchorId,options).map(r=>r.element.id),distance:model.elements.filter(x=>x.id!==e.id&&G.centerDistance(e,x)<=radius).map(x=>x.id)};const result={caseId:c.caseId,anchorId:c.anchorId};for(const method of ['spatial','distance']){const evaluated=predicted[method].filter(id=>scope.has(id)),m=G.evaluate(evaluated,c.confirmedIds);m.ignored=predicted[method].length-evaluated.length;result[method]=m;for(const k of ['tp','fp','fn','ignored'])totals[method][k]+=m[k]}return result});for(const t of Object.values(totals)){t.precision=t.tp+t.fp?t.tp/(t.tp+t.fp):null;t.recall=t.tp+t.fn?t.tp/(t.tp+t.fn):null}return{buildingId:buildingId(model),referenceType:dataset.referenceType,source:dataset.source,reviewer:dataset.reviewer,reviewedAt:dataset.reviewedAt,provenance:'user_supplied_reference_not_independently_verified',radius,relationOptions:options,cases,totals}}
root.SpatiaWorkspace={MODEL_KEY,OPS_KEY,buildingId,ids,reconcile,validationDataset,compare};
})(typeof module==='object'?module.exports:globalThis);
